param([Parameter(Mandatory=$true)][string]$OutputDirectory)
$ErrorActionPreference='Stop'
if($PSVersionTable.PSVersion.Major-lt7){throw 'Bundled PowerShell7 required'}
$carryRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$carryOut=[IO.Path]::GetFullPath($OutputDirectory);$carryAllowed=Join-Path $carryRoot 'reports/m4-fp-numeric-max-carry';$carryName=Split-Path $carryOut -Leaf
if([IO.Path]::GetDirectoryName($carryOut)-ne$carryAllowed -or $carryName-notmatch'^[a-z][a-z0-9-]{0,63}$'){throw 'Immediate private carry directory required'}
$carryTrees=@{};foreach($carryLevel in @('O0','O2')){$carryTrees[$carryLevel]=Join-Path $carryRoot "build/m4-nmx-carry-$carryName-$carryLevel"}
foreach($carryPath in @($carryOut)+@($carryTrees.Values)){if(Test-Path -LiteralPath $carryPath){throw 'Entire output/all builds must be fresh before mutation'}}
function Hash-Carry([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
New-Item -ItemType Directory -Force -Path $carryOut|Out-Null;$carrySources=[ordered]@{};$carryCopies=[Collections.Generic.List[object]]::new()
foreach($carryFile in @((Get-ChildItem -LiteralPath $PSScriptRoot -File);(Get-Item (Join-Path $carryRoot 'tools/m4-fp-numeric-max/protocol.hpp'));(Get-Item (Join-Path $carryRoot 'tools/m4-fp-numeric-max/corpus.hpp')))){$carrySources[$carryFile.FullName]=Hash-Carry $carryFile.FullName;$carryCopy=Join-Path $carryOut ('sources/'+[IO.Path]::GetRelativePath($carryRoot,$carryFile.FullName));New-Item -ItemType Directory -Force -Path (Split-Path $carryCopy)|Out-Null;Copy-Item -LiteralPath $carryFile.FullName -Destination $carryCopy;$carryCopies.Add([ordered]@{original_path=$carryFile.FullName;preserved_path=$carryCopy;sha256=$carrySources[$carryFile.FullName]})}
$carryVS='C:/Program Files/Microsoft Visual Studio/18/Community';$carryLLVM=Join-Path $carryRoot 'local/tools/llvm-21.1.8/clang+llvm-21.1.8-x86_64-pc-windows-msvc/bin';$carryCMake=Join-Path $carryVS 'Common7/IDE/CommonExtensions/Microsoft/CMake/CMake/bin/cmake.exe';$carryNinja=Join-Path $carryVS 'Common7/IDE/CommonExtensions/Microsoft/CMake/Ninja/ninja.exe';$carryCommands=[Collections.Generic.List[object]]::new();$carryTools=[ordered]@{};$carryPassed=$false;$carryFailure=$null
function Run-Carry([string]$p,[string[]]$a,[string]$log){$carryTools[$p]=Hash-Carry $p;[IO.File]::WriteAllText($log,'');$carrySave=$ErrorActionPreference;$ErrorActionPreference='Continue';try{&$p @a 2>&1|Tee-Object -FilePath $log|Out-Null;$carryExit=$LASTEXITCODE}finally{$ErrorActionPreference=$carrySave};$carryCommands.Add([ordered]@{program=$p;arguments=$a;exit_code=$carryExit;log_path=$log;log_sha256=(Hash-Carry $log)});if($carryExit-ne0){throw "Hardware carry unit tool failed exit=$carryExit"}}
try{Import-Module (Join-Path $carryVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll');Enter-VsDevShell -VsInstallPath $carryVS -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64'|Out-Null;$env:PATH="$carryLLVM;$(Split-Path $carryNinja);$env:PATH";$carryTemp=Join-Path $carryOut 'compiler-temp';New-Item -ItemType Directory $carryTemp|Out-Null;$env:TEMP=$carryTemp;$env:TMP=$carryTemp;$env:TMPDIR=$carryTemp
 foreach($carryLevel in @('O0','O2')){$carryOpt=if($carryLevel-eq'O0'){'/Od'}else{'/O2'};Run-Carry $carryCMake @('-G','Ninja','-S',$PSScriptRoot,'-B',$carryTrees[$carryLevel],'-DCMAKE_BUILD_TYPE=Release',"-DCMAKE_CXX_COMPILER=$carryLLVM/clang-cl.exe","-DCMAKE_CXX_FLAGS_RELEASE=$carryOpt /DNDEBUG /showIncludes") (Join-Path $carryOut "configure-$carryLevel.log");Run-Carry $carryCMake @('--build',$carryTrees[$carryLevel],'--verbose','--parallel','4') (Join-Path $carryOut "build-$carryLevel.log");Run-Carry (Join-Path $carryTrees[$carryLevel] 'mw34_nmx_carry_probe.exe') @((Join-Path $carryOut "hardware-$carryLevel.bin")) (Join-Path $carryOut "hardware-$carryLevel.log")}
 foreach($carryPath in $carrySources.Keys){if((Hash-Carry $carryPath)-ne$carrySources[$carryPath]){throw 'Carry source changed during actual unit build'}};$carryPassed=$true
}catch{$carryFailure=$_.Exception.Message;$_|Out-String|Set-Content (Join-Path $carryOut 'failure.txt');throw}finally{$carryArtifacts=[ordered]@{};foreach($carryPath in @($carryOut)+@($carryTrees.Values)){if(Test-Path -LiteralPath $carryPath){foreach($carryFile in Get-ChildItem -LiteralPath $carryPath -Recurse -File|Where-Object {$_.FullName-notmatch'compiler-temp'}){$carryArtifacts[$carryFile.FullName]=Hash-Carry $carryFile.FullName}}};foreach($carryTool in @($carryCMake,$carryNinja,(Get-Process -Id $PID).Path,(Join-Path $carryLLVM 'clang-cl.exe'),(Join-Path $carryLLVM 'lld-link.exe'))){$carryTools[$carryTool]=Hash-Carry $carryTool};[ordered]@{passed=$carryPassed;failure=$carryFailure;scope='Authored local x64 hardware FLD/FSTP carry unit only; no original process/code/guest metadata equivalence';source_files=$carrySources;literal_sources=@($carryCopies);tools=$carryTools;artifacts=$carryArtifacts;commands=@($carryCommands);build_directories=$carryTrees;original_executed=$false;frozen_source_modified=$false}|ConvertTo-Json -Depth 12|Set-Content -Encoding utf8 (Join-Path $carryOut 'build.json')}
